```javascript
// Get the search component elements
const searchInput = document.getElementById('search-input');
const searchButton = document.getElementById('search-button');
const searchPredictions = document.getElementById('search-predictions');
const searchError = document.getElementById('search-error');
const searchComponent = document.querySelector('.search-component');

// Google Search functionality
const googleSearch = async (query) => {
  const response = await fetch(`https://www.google.com/search?q=${query}`);
  const results = await response.json();
  return results;
};

// Predictive search functionality
searchInput.addEventListener('input', async (e) => {
  const query = e.target.value;
  if (query.length > 2) {
    const results = await googleSearch(query);
    searchPredictions.innerHTML = '';
    results.forEach((result) => {
      const prediction = document.createElement('div');
      prediction.textContent = result.title;
      searchPredictions.appendChild(prediction);
    });
    searchPredictions.classList.add('show');
  } else {
    searchPredictions.classList.remove('show');
  }
});

// Error handling
searchInput.addEventListener('input', (e) => {
  const query = e.target.value;
  if (query.includes('pornographically motivated')) {
    searchError.textContent = 'Error: Not suitable for viewing';
    searchError.classList.add('show');
  } else {
    searchError.classList.remove('show');
  }
});

// Disable functionality
searchComponent.addEventListener('click', (e) => {
  if (e.target.id === 'search-input') {
    searchInput.disabled = 'disabled';
  } else if (e.target.id === 'search-button') {
    searchButton.disabled = 'disabled';
  }
  searchComponent.classList.add('disabled');
});

// Enable functionality
searchComponent.addEventListener('click', (e) => {
  if (e.target.id === 'search-input' || e.target.id === 'search-button') {
    searchInput.disabled = '';
    searchButton.disabled = '';
  }
  searchComponent.classList.remove('disabled');
});
```
